var RX_BODY = window.RX_BODY || {};

RX_BODY['paromomycin'] = {
  what: {
    ar: 'الباروموميسين مضاد حيوي من فصيلة الأمينوغليكوزيدات، لكن موضعه الحقيقي بين أدوية الطفيليات. وخاصّته الحاكمة أنه لا يكاد يُمتصّ إلى الدم حين يُبلع: النشرة الرسمية تقول إن الدواء يُستردّ من البراز كاملاً تقريباً. فهو يبقى عاملاً داخل تجويف الأمعاء وحده، ولهذا صار خياراً للأميبا التي تسكن الأمعاء، وعاجزاً تماماً عن ملاحقتها إن خرجت منها إلى الكبد. وله شكل آخر يُحقن في العضل ويُستعمل في الليشمانيا، وهذا الشكل يدخل الدم فيحمل معه ما تُعرف به فصيلته من أثر على السمع والكلى.',
    en: 'Paromomycin is an aminoglycoside antibiotic, but its real place is among the antiparasitic medicines. Its governing property is that it is barely absorbed into the blood when swallowed: the official label states that almost all of the drug is recovered in the stool. It therefore acts inside the bowel cavity alone, which is why it became an option for amoebae living in the gut and is entirely unable to pursue them once they leave it for the liver. A separate form is injected into muscle and used in leishmaniasis, and that form does enter the blood, carrying with it the effects on hearing and kidneys that its class is known for.'
  },
  why: {
    ar: 'النشرة الأمريكية تعتمده في حالتين. الأولى الزحار الأميبي المعوي، حادّاً كان أو مزمناً، مع تنبيه صريح أنه لا يفيد في الأميبا خارج الأمعاء. والثانية علاج مساعد في الغيبوبة الكبدية، إذ يخفّض البكتيريا المعوية التي تصنع النشادر فتقلّ حمولة الدماغ. وله استعمال ثالث خارج هذه النشرة: منظمة الصحة العالمية تُدرج حقنته العضلية في علاج الليشمانيا الحشوية، ودليلها المحدَّث يوصي بها مقرونةً بالميلتيفوسين في شرق أفريقيا بدل التركيبة القديمة.',
    en: 'The United States label approves it in two situations. The first is intestinal amoebic dysentery, acute or chronic, with an explicit note that it does not help amoebiasis outside the bowel. The second is as adjunctive therapy in hepatic coma, where it lowers the gut bacteria that produce ammonia and so reduces the load on the brain. It has a third use outside that label: the World Health Organization includes its intramuscular injection in the treatment of visceral leishmaniasis, and its updated guideline recommends it paired with miltefosine in eastern Africa in place of the older regimen.'
  },
  how: {
    ar: 'الباروموميسين يلتصق بمصنع البروتين داخل الكائن الدقيق فيعطّله، ونشرته تقول إن فعله المضاد للجراثيم يوازي النيومايسين موازاةً قريبة. والفرق الذي يصنع كل شيء هو المكان: لأنه لا يعبر جدار الأمعاء إلى الدم، فتركيزه يبقى عالياً حيث الطفيل نفسه ومنخفضاً في باقي الجسم. في الغيبوبة الكبدية يُستفاد من هذا المعنى نفسه، إذ يقلّل البكتيريا المولّدة للنشادر داخل الأمعاء. أمّا الحقنة العضلية فتتخطّى الأمعاء كلها وتصل الدم لتبلغ الطفيل في نخاع العظم والطحال والكبد.',
    en: 'Paromomycin attaches to the protein factory inside the micro-organism and disables it; its label states that its antibacterial action closely parallels that of neomycin. The difference that makes everything is location: because it does not cross the bowel wall into the blood, its concentration stays high where the parasite is and low everywhere else. In hepatic coma the same principle is used, as it reduces the ammonia-producing bacteria inside the gut. The intramuscular injection, by contrast, bypasses the bowel entirely and reaches the blood so as to meet the parasite in the marrow, spleen and liver.'
  },
  effects: {
    ar: 'الشكل المبلوع لطيف في الغالب لأنه لا يدخل الدم، وما تذكره النشرة من آثار يقع عند الكميات الأكبر: غثيان ومغص في البطن وإسهال. وتنبّه النشرة إلى معنى آخر: أي مضاد حيوي يفتح الباب لنمو كائنات لا يقتلها، ومنها الفطريات، فيلزم أن يبقى المريض تحت الملاحظة. أمّا الحقنة العضلية المستعملة في الليشمانيا فآثارها من طراز آخر، إذ يدخل الدواء الدم، والمتابعات المنشورة تصف ارتفاعاً في إنزيمات الكبد وألماً في موضع الحقن وتأثّراً عابراً في السمع عند قلّة من المرضى.',
    en: 'The swallowed form is usually gentle because it does not enter the blood, and the effects the label lists appear with larger amounts: nausea, abdominal cramps and diarrhoea. The label flags another point: any antibiotic opens the door to the growth of organisms it does not kill, fungi among them, so the patient must remain under observation. The intramuscular injection used in leishmaniasis is a different matter, since the drug does enter the blood; published follow-up describes raised liver enzymes, pain at the injection site and transient hearing effects in a minority of patients.'
  },
  warning: {
    ar: 'اذهب للطوارئ فوراً إن ظهرت علامات حساسية شديدة: تورّم الوجه أو اللسان، ضيق نفس، طفح واسع مفاجئ. وتوقّف واتصل بالطبيب في يومك إن جاءك إسهال مائي شديد أو مصحوب بدم بعد بدء الدواء، أو مغص شديد مع انتفاخ وانقطاع الريح والبراز فإن انسداد الأمعاء مانع لهذا الدواء. والأخطر من هذا كله سكوت: الباروموميسين لا يعمل خارج الأمعاء، فإن ارتفعت حرارتك أو وجعك أعلى البطن من اليمين أو اصفرّت عيناك فالأميبا قد تكون بلغت الكبد وتحتاج دواءً آخر عاجلاً. ومع الحقنة العضلية: طنين أو نقص سمع أو دوار أو قلّة بول تستدعي مراجعة فورية.',
    en: 'Go to emergency at once if signs of a severe allergy appear: swelling of the face or tongue, breathlessness, a sudden widespread rash. Stop and call your doctor the same day if you develop severe watery or bloody diarrhoea after starting, or severe cramping with bloating and no passage of wind or stool, since bowel obstruction is a bar to this medicine. More dangerous than all of these is a silence: paromomycin does not work outside the bowel, so if your temperature rises, or you ache in the upper right abdomen, or your eyes yellow, the amoebae may have reached the liver and need a different medicine urgently. With the injection, ringing in the ears, hearing loss, dizziness or reduced urine call for immediate review.'
  },
  interact: {
    ar: 'النشرة الأمريكية لا تسجّل تعارضات دوائية موثّقة للشكل المبلوع، والسبب مفهوم: الدواء لا يبلغ الدم فلا يزاحم غيره فيه. لكن هذا الأمان مشروط بسلامة بطانة الأمعاء، ولذلك تُوصي النشرة بالحذر عند من عنده تقرّحات معوية، لأن الجدار المتقرّح قد يسمح بامتصاص جزء من الدواء فيظهر أثره على الكلى. وعند استعمال الحقنة العضلية يتغيّر الحساب كلياً: صار الدواء في الدم، وتصبح مشاركة أدوية أخرى مؤذية للكلى أو للسمع مسألة يقرّرها الطبيب بعد موازنة.',
    en: 'The United States label records no documented drug interactions for the swallowed form, and the reason is plain: the drug never reaches the blood, so it does not compete with anything there. But that safety is conditional on an intact bowel lining, which is why the label advises caution in people with ulcerative lesions of the bowel, since an ulcerated wall may allow part of the drug to be absorbed and its effect on the kidneys to appear. With the intramuscular injection the calculation changes entirely: the drug is now in the blood, and combining it with other medicines toxic to the kidney or the hearing becomes a decision the doctor weighs.'
  },
  avoid: {
    ar: 'ممنوع على من سبقت له حساسية من الباروموميسين، وعلى من عنده انسداد في الأمعاء. ويُذكر في نشرات أخرى أن الحساسية من الأمينوغليكوزيدات عموماً كالجنتاميسين والأميكاسين قد تمتدّ إليه، فأخبر طبيبك بها. ويُتحرّى الحذر عند من في أمعائه تقرّحات لأن الامتصاص يزيد. ولا يصلح وحده لأميبا الكبد. والنشرة الأمريكية لا تتضمّن بياناً عن الحمل والرضاعة، فالقرار للطبيب موازنةً بين خطر العدوى وخطر الدواء، والحقنة العضلية تحتاج موازنة أدقّ عند مرضى الكلى وكبار السن.',
    en: 'It is forbidden to anyone with a previous hypersensitivity reaction to paromomycin, and to anyone with intestinal obstruction. Other labels note that allergy to aminoglycosides in general, such as gentamicin and amikacin, may extend to it, so tell your doctor about that. Caution is exercised in people with ulcerative bowel lesions because absorption increases. It is not adequate on its own for amoebae in the liver. The United States label carries no statement on pregnancy and breastfeeding, so the decision rests with the doctor weighing the risk of the infection against the risk of the medicine, and the injection needs a finer judgement in kidney patients and the elderly.'
  },
  updated: '2026-09-10',
  src: [
    'https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=a725f022-ec3c-430d-8021-96c861b9893c',
    'https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=333d55f0-ab49-459e-8d32-1590b2623ef3',
    'https://www.who.int/news/item/29-07-2026-who-updates-treatment-guidelines-on-visceral-and-post-kala-azar-dermal-leishmaniasis',
    'https://www.ncbi.nlm.nih.gov/books/NBK544251/'
  ]
};

RX_BODY['miltefosine'] = {
  what: {
    ar: 'الميلتيفوسين كبسولة تُبلع، وهو أول دواء فعّال للّيشمانيا يؤخذ عن طريق الفم بعد أن كان العلاج حقناً لا غير. أصله من أدوية الأورام ثم تبيّن أثره في هذا الطفيل. تعتمده الإدارة الأمريكية للّيشمانيا الحشوية والجلدية والمخاطية، لكل شكل أنواع محدّدة من الطفيل مذكورة بالاسم في النشرة، والاستجابة تختلف باختلاف المنطقة الجغرافية. وهو مقصور على من بلغ سنّ الثانية عشرة وتجاوز حدّاً من الوزن، ويُبلع مع الطعام.',
    en: 'Miltefosine is a swallowed capsule, and the first effective oral medicine for leishmaniasis after treatment had been injections only. It came from cancer medicine and was then found to act on this parasite. The United States authority approves it for visceral, cutaneous and mucosal leishmaniasis, each form with specific parasite species named in the label, and the response differs by geographical region. It is restricted to those who have reached the age of twelve and passed a weight threshold, and it is taken with food.'
  },
  why: {
    ar: 'يوصف للّيشمانيا الحشوية، وهي الشكل الذي يهاجم الطحال والكبد ونخاع العظم ويُعرف بالكالازار. ويوصف للّيشمانيا الجلدية، تلك القرحة المزمنة التي تُسمّى عندنا حبّة بغداد وتترك أثراً إن أُهملت. ويوصف للشكل المخاطي الذي يأكل الأنف والحلق. والنشرة تنصّ على أنواع الطفيل المشمولة بكل دواعٍ، وأن الفعالية في أنواع غيرها غير مثبتة. وقد صعد موضعه أكثر بعد أن أوصت به منظمة الصحة العالمية مقروناً بحقنة الباروموميسين في شرق أفريقيا.',
    en: 'It is prescribed for visceral leishmaniasis, the form that attacks the spleen, liver and bone marrow and is known as kala-azar. It is prescribed for cutaneous leishmaniasis, that chronic sore known in our region as the Baghdad boil, which leaves a scar if neglected. And it is prescribed for the mucosal form that eats into the nose and throat. The label names the parasite species covered by each indication and states that efficacy against others is not established. Its standing rose further when the World Health Organization recommended it paired with paromomycin injection in eastern Africa.'
  },
  how: {
    ar: 'الميلتيفوسين لا يقتل الطفيل بضربة واحدة كما يفعل مضاد حيوي، بل يعمل من داخله. تشرح النشرة أنه يتفاعل مع دهون الطفيل ويثبّط إنزيماً اسمه سيتوكروم سي أوكسيديز مسؤولاً عن عمل الميتوكوندريا، أي مصنع الطاقة في الخلية، فتنقطع طاقة الطفيل ويموت موتاً يشبه الانتحار المبرمج للخلية. ولأنه يتعامل مع أغشية دهنية فإن الطعام الدهني يساعد امتصاصه، ولهذا تشترط النشرة بلعه مع الأكل لا على معدة فارغة.',
    en: 'Miltefosine does not kill the parasite with a single blow as an antibiotic does; it works from inside it. The label explains that it interacts with the parasite lipids and inhibits an enzyme called cytochrome c oxidase, which runs the mitochondria, the cell power plant, so the parasite energy is cut off and it dies a death resembling programmed cell suicide. Because it deals with fatty membranes, food aids its absorption, which is why the label requires it be swallowed with a meal and not on an empty stomach.'
  },
  effects: {
    ar: 'أغلب ما يشكوه المرضى من الجهاز الهضمي: القيء والغثيان في نحو ثلث من عولجوا في التجارب، والإسهال في نحو خمسهم، وضعف الشهية وألم البطن. ويُذكر الصداع والدوخة. وقد يرتفع الكرياتينين علامةً على إجهاد الكلى، وترتفع إنزيمات الكبد، وتنخفض الصفيحات في مرضى الشكل الحشوي، ولذلك تُطلب هذه الفحوص أثناء العلاج وبعده. وسُجّل عند الرجال ألم في الصفن واضطراب في القذف. وأغلب الاضطراب الهضمي يمرّ، لكن معالجته بالسوائل ليست تحسيناً للراحة بل وقاية للكلية.',
    en: 'Most complaints are digestive: vomiting and nausea in roughly a third of those treated in the trials, diarrhoea in about a fifth, poor appetite and abdominal pain. Headache and dizziness are also reported. Creatinine may rise as a sign of strain on the kidneys, liver enzymes may rise, and platelets may fall in patients with the visceral form, which is why these tests are requested during and after treatment. In men, scrotal pain and abnormal ejaculation have been recorded. Most of the digestive upset passes, but treating it with fluids is not a comfort measure; it protects the kidney.'
  },
  warning: {
    ar: 'أوقف الدواء واطلب الطوارئ فوراً إن ظهر طفح يتقشّر أو يصنع فقاعات أو يصيب الفم والعينين، فهذه صورة متلازمة ستيفنز جونسون وتنصّ النشرة على الإيقاف الفوري. وراجع في يومك إن استمرّ القيء أو الإسهال حتى عجزت عن شرب الماء، لأن الجفاف هنا يؤذي الكلى، أو إن قلّ بولك أو اسودّ لونه. وراجع أيضاً عند كدمات بلا سبب أو نزف من الأنف أو اللثة أو نقاط حمراء تحت الجلد، وعند اصفرار العين أو ألم يمين البطن الأعلى. وإن كنت امرأة وتأخّرت دورتك أثناء العلاج فأخبري طبيبك في يومك.',
    en: 'Stop the medicine and seek emergency care at once if a rash appears that peels, blisters, or involves the mouth and eyes, as this is the picture of Stevens-Johnson syndrome and the label directs immediate discontinuation. Seek review the same day if vomiting or diarrhoea continues until you cannot drink, because dehydration here injures the kidneys, or if your urine falls off or darkens. Seek review also for bruising without cause, bleeding from the nose or gums, red pinpoints under the skin, yellowing of the eyes or pain in the upper right abdomen. And if you are a woman whose period is late during treatment, tell your doctor that day.'
  },
  interact: {
    ar: 'النشرة تصف الميلتيفوسين بأنه هادئ من جهة التعارض الدوائي: لم يظهر له في الدراسات المخبرية والحيوانية تثبيط ولا تحفيز مهم لإنزيمات السيتوكروم التي تُصرَّف بها أغلب الأدوية. لكن التعارض المهمّ عملياً غير مباشر: القيء والإسهال يُبطلان امتصاص حبوب منع الحمل الهرمونية، والنشرة تُلزم بوسيلة إضافية للمنع. وهذا ليس تفصيلاً، لأن الحمل ممنوع مع هذا الدواء أصلاً. وأي دواء آخر يجهد الكلى أو الكبد يستحقّ أن يُذكر للطبيب قبل البدء.',
    en: 'The label describes miltefosine as quiet on the interaction front: laboratory and animal studies showed no significant inhibition or induction of the cytochrome enzymes through which most medicines are cleared. But the interaction that matters in practice is indirect: vomiting and diarrhoea defeat the absorption of hormonal contraceptive pills, and the label requires an additional method of contraception. This is no detail, since pregnancy is forbidden with this medicine in the first place. Any other medicine that burdens the kidney or the liver deserves to be mentioned to the doctor before starting.'
  },
  avoid: {
    ar: 'ممنوع في الحمل منعاً باتاً، وهذا مضمون التحذير المؤطّر: ثبت في الحيوان موت الجنين وتشوّهه بكميات أقلّ من المستعملة في الإنسان. وتُلزم النشرة بفحص حمل قبل الوصف لكل امرأة في سنّ الإنجاب، وبمنع حمل فعّال أثناء العلاج ولخمسة أشهر بعده. ولا تُرضع الأم في هذه المدة نفسها. وممنوع في متلازمة شوغرن لارسون، وعند الحساسية منه. ولم تُثبت سلامته دون سنّ الثانية عشرة. وقد أضرّ بخصوبة ذكور الجرذان وإناثها، وأثره في خصوبة الإنسان غير مدروس كفاية.',
    en: 'It is absolutely forbidden in pregnancy, and this is the substance of its boxed warning: fetal death and malformation were shown in animals at amounts lower than those used in humans. The label requires a pregnancy test before prescribing to any woman of reproductive potential, and effective contraception during treatment and for five months after. The mother must not breastfeed over that same period. It is forbidden in Sjogren-Larsson syndrome and in hypersensitivity to it. Its safety below the age of twelve is not established. It impaired fertility in male and female rats, and its effect on human fertility is not adequately studied.'
  },
  updated: '2026-09-10',
  src: [
    'https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=bcb387ac-2e90-4f5e-94b2-d3635190678e',
    'https://www.who.int/news/item/29-07-2026-who-updates-treatment-guidelines-on-visceral-and-post-kala-azar-dermal-leishmaniasis',
    'https://www.who.int/publications/i/item/9789240123298'
  ]
};

RX_BODY['meglumine-antimoniate'] = {
  what: {
    ar: 'أنتيمونات الميجلومين محلول يُحقن، مادّته الفعّالة معدن الأنتيمون في صورته الخماسية التكافؤ. وهو من أقدم ما عُولجت به الليشمانيا وما زال مستعملاً. يُعطى حقناً في العضل حين يكون المرض واسعاً أو حشوياً، أو يُحقن مباشرة في قاعدة القرحة الجلدية حتى يبيضّ ما تحتها حين تكون القرحة واحدة مبكّرة. وتصنيفه الدوائي مضاد ليشمانيا لا غير، ويحتوي المحلول على كبريتيت قد يثير حساسية شديدة عند القليل من الناس.',
    en: 'Meglumine antimoniate is an injectable solution whose active substance is the metal antimony in its pentavalent form. It is among the oldest treatments for leishmaniasis and is still in use. It is given into the muscle when the disease is widespread or visceral, or injected directly into the base of the skin sore until the tissue beneath blanches, when the sore is single and early. Its drug class is antileishmanial and nothing else, and the solution contains sulphite, which can provoke severe hypersensitivity in a few people.'
  },
  why: {
    ar: 'تنصّ النشرة على دواعيه: الليشمانيا الحشوية المعروفة بالكالازار، والليشمانيا الجلدية باستثناء النوع المقاوم منها. وتفصّل متى يُكتفى بالحقن الموضعي في القرحة ومتى يلزم العلاج العام: يلزم العام حين تكون الآفات كثيرة أو ملتهبة أو متقرّحة، أو في موضع تُخلّف فيه الندبة تشويهاً أو إعاقة، وخاصةً إذا انسدّت القنوات اللمفاوية أو أُصيب الغضروف. وللأشكال الجلدية المخاطية في أمريكا الجنوبية مسار علاجي أطول تحدّده النشرة بحسب نوع الطفيل.',
    en: 'The label states its indications: visceral leishmaniasis, known as kala-azar, and cutaneous leishmaniasis apart from the resistant species. It details when local injection into the sore suffices and when systemic treatment is required: systemic treatment is needed when lesions are numerous, inflamed or ulcerated, or sit where a scar would be disfiguring or disabling, especially if the lymphatic channels are obstructed or cartilage is damaged. The mucocutaneous forms of South America follow a longer course that the label sets out according to the parasite species.'
  },
  how: {
    ar: 'النشرة تكتفي بالقول إن للمادة فعلاً قاتلاً لليشمانيا، وهذا صدق علمي لا نقص فيه. والمراجع الطبية تشرح الآلية المرجّحة: الأنتيمون الخماسي يتحوّل داخل الطفيل إلى صورته الثلاثية فيعطّل تحويل الطاقة، إذ يمنع فسفرة المركّبات التي تُصنع منها طاقة الخلية، فيتعطّل تحلّل السكر ودورة حمض الستريك عند الطفيل ويموت جوعاً من الطاقة. ويُطرح الدواء سريعاً في البول، إذ يخرج أكثر من أربعة أخماس الكمية دون تغيير خلال ساعات قليلة، ولهذا كانت الكلية موضع مراقبة.',
    en: 'The label limits itself to saying that the substance has leishmanicidal activity, which is honest science rather than a gap. Medical references explain the likely mechanism: pentavalent antimony is converted inside the parasite to its trivalent form and disables energy conversion by blocking the phosphorylation of the compounds from which cell energy is built, so glycolysis and the citric acid cycle stall in the parasite and it starves of energy. The drug is cleared quickly in the urine, more than four-fifths of it leaving unchanged within a few hours, which is why the kidney is a place of watchfulness.'
  },
  effects: {
    ar: 'أكثر ما يُشتكى منه شائع جداً بنصّ النشرة: صداع وألم مفاصل وألم عضلات. ويكثر أيضاً ضعف الشهية والغثيان والقيء وألم البطن. ومن المتوقّع أن يظهر في تخطيط القلب طول في فترة كيو تي، وهذا شائع، ويقلّ منه انقلاب موجة تي. ونادراً يظهر طفح أو ضيق نفس أو رعشة أو توعّك أو اضطراب نظم. وذُكرت بلا تقدير للتواتر: التهاب البنكرياس، وفشل كلوي حادّ، وارتفاع إنزيمات الكبد، وحمّى وتعرّق وتورّم الوجه. وكثير من هذا يظهر في بداية العلاج ثم يهدأ.',
    en: 'What is complained of most is very common in the words of the label: headache, joint pain and muscle pain. Poor appetite, nausea, vomiting and abdominal pain are also frequent. Prolongation of the QT interval on the ECG is to be expected and is frequent, with T-wave inversion less so. Rarely a rash, breathlessness, chills, malaise or arrhythmia appear. Reported without an estimate of frequency are pancreatitis, acute kidney failure, raised liver enzymes, fever, sweating and swelling of the face. Much of this appears at the start of treatment and then settles.'
  },
  warning: {
    ar: 'اطلب الطوارئ فوراً عند خفقان أو دوخة تسبق الإغماء أو إغماء فعلي: النشرة تقول إن انقلاب موجة تي وطول فترة كيو تي يسبقان في الغالب ظهور اضطراب نظم خطير. واطلبها أيضاً عند علامات حساسية شديدة، وعند أزيز وضيق نفس مفاجئ لأن الكبريتيت في المحلول قد يسبّب تشنّج قصبات. وراجع في يومك عند ألم شديد أعلى البطن ينفذ إلى الظهر مع قيء، فهذه صورة التهاب البنكرياس. وراجع عند اصفرار العين أو بول داكن أو قلّة بول. ولا تغب عن مواعيد التخطيط وتحليل الكبد والكلى فهي جزء من العلاج لا زيادة عليه.',
    en: 'Seek emergency care at once for palpitations, near-fainting dizziness or an actual faint: the label states that T-wave inversion and QT prolongation most commonly precede the appearance of a serious arrhythmia. Seek it also for signs of severe allergy, and for sudden wheeze and breathlessness, since the sulphite in the solution can cause bronchospasm. Seek review the same day for severe upper abdominal pain boring through to the back with vomiting, which is the picture of pancreatitis. Seek review for yellowing of the eyes, dark urine or reduced urine output. And do not miss the ECG and liver and kidney test appointments; they are part of the treatment, not an addition to it.'
  },
  interact: {
    ar: 'الخطّ الأخطر هو الأدوية التي تطيل فترة كيو تي، إذ يجتمع أثرها مع أثر الأنتيمون. تسمّي النشرة أصنافاً بعينها: مضادات اضطراب النظم من الفئتين الأولى أ والثالثة، وبعض مضادات الاكتئاب ثلاثية الحلقة، وبعض الماكروليدات، وبعض مضادات الذهان، وبعض أدوية الطفيليات الأخرى. وتزيد الخطورة إذا اجتمع مع ذلك اختلال في أملاح الدم كنقص البوتاسيوم أو المغنيسيوم، أو بطء في النبض، أو مرض قلبي سابق. فأعطِ الطبيب قائمة كل ما تأخذه، ومنه ما يُصرف بلا وصفة.',
    en: 'The most dangerous line is medicines that prolong the QT interval, since their effect combines with that of antimony. The label names specific groups: class IA and class III antiarrhythmics, some tricyclic antidepressants, some macrolides, some antipsychotics, and some other antiparasitic drugs. The danger increases if a disturbance in the blood salts, such as low potassium or magnesium, or a slow pulse, or existing heart disease is present as well. So give the doctor a list of everything you take, including what is sold without a prescription.'
  },
  avoid: {
    ar: 'ممنوع عند الحساسية من المادة أو من أي مكوّن، وممنوع في فشل الكلى أو القلب أو الكبد. ويُحذَّر من استعماله عند من عنده متلازمة كيو تي الطويلة الخلقية أو مرض قلبي كاحتشاء سابق أو بطء نبض أو اختلال أملاح غير مصحَّح. ولا يُعطى في الحمل إلا في حالة مهدِّدة للحياة يرجّح فيها الطبيب نفع الأم على خطر الجنين، وقد لوحظ في الحيوان أثر قاتل للجنين وتأخّر نموّ بكميات أعلى بكثير. ولا يُنصح بالإرضاع أثناء العلاج لأن انتقاله إلى الحليب غير معروف.',
    en: 'It is forbidden in hypersensitivity to the substance or any component, and forbidden in kidney, heart or liver failure. Caution is required in congenital long QT syndrome, in heart disease such as a previous infarction, in slow pulse, and in uncorrected salt imbalance. It is not given in pregnancy except in a life-threatening situation where the doctor judges the benefit to the mother to outweigh the risk to the fetus; in animals an embryolethal effect and developmental delay were seen at far higher amounts. Breastfeeding is not advised during treatment because its passage into milk is not known.'
  },
  updated: '2026-09-10',
  src: [
    'https://www.huidziekten.nl/formularium/bijsluiters/bijsluiter-glucantime-meglumine-antimonate.pdf',
    'https://www.ncbi.nlm.nih.gov/books/NBK544251/',
    'https://www.who.int/publications/i/item/9789240123298'
  ]
};

RX_BODY['sodium-stibogluconate'] = {
  what: {
    ar: 'ستيبوجلوكونات الصوديوم محلول حقن يحمل الأنتيمون الخماسي التكافؤ، وهو التوأم الآخر لأنتيمونات الميجلومين. يُعطى في العضل أو في الوريد أو داخل القرحة الجلدية. وله تفصيل تقنيّ مهمّ تنصّ عليه النشرة: في المحلول جسيمات دقيقة تتكوّن من تفاعل المادة الحافظة مع سدادة القارورة المطاطية، فيجب سحبه عبر مرشّح قبل الحقن مباشرة، وأن يُعطى وريدياً ببطء شديد لتقليل خطر تجلّط الوريد.',
    en: 'Sodium stibogluconate is an injectable solution carrying pentavalent antimony, the other twin of meglumine antimoniate. It is given into muscle, into a vein, or into the skin sore itself. It has an important technical detail set out in its label: the solution contains fine particles formed by the reaction of the preservative with the rubber stopper of the vial, so it must be drawn through a filter immediately before injection and given intravenously very slowly to reduce the risk of clotting the vein.'
  },
  why: {
    ar: 'تعتمده النشرة البريطانية في الليشمانيا الحشوية المعروفة بالكالازار، وفي الليشمانيا الجلدية، وفي الشكل الجلدي المخاطي في أمريكا الجنوبية. وقد يفيد أيضاً في الليشمانيا الناكسة وفي الشكل الجلدي المنتشر في العالم الجديد، وهذان تُنصح فيهما التركيبة مع دواء آخر لا العلاج المفرد. وتنبّه النشرة إلى قلّة البيانات في أنواع بعينها من الطفيل، وإلى أن العلاج المفرد به غير موصى به في نوع منها، وإلى وجوب اتّباع أدلة العلاج الدولية والمحلية وأنماط المقاومة قبل الوصف.',
    en: 'The British label approves it for visceral leishmaniasis, known as kala-azar, for cutaneous leishmaniasis, and for South American mucocutaneous leishmaniasis. It may also help in leishmaniasis recidivans and in diffuse cutaneous leishmaniasis of the New World, and for these two a combination rather than single-drug therapy is advised. The label notes the limited data for particular parasite species, that monotherapy is not recommended for one of them, and that international and local treatment guidelines and resistance patterns must be followed before prescribing.'
  },
  how: {
    ar: 'تقول النشرة بصراحة إن آلية عمله غير معروفة، وهذا أنفع من تخمين. والمعروف مخبرياً أن تعريض الطفيل له يُنقص حمضه النووي وبروتينه ومركّبات الطاقة فيه إنقاصاً كبيراً، وقد رُجّح أن نقص طاقة الخلية هو ما يوقف بناءها لجزيئاتها الكبيرة. أمّا مصير الدواء في الجسم فسريع: يخرج الأنتيمون عبر الكليتين، ويظهر معظمه في بول الساعات الأولى. لكن مع تكرار الحقن يوماً بعد يوم يتراكم ببطء في الأنسجة حتى يبلغ حدّاً أعلى بعد أيام، وهنا تنشأ سميّته.',
    en: 'The label says plainly that its mode of action is unknown, which is more useful than a guess. What is known in the laboratory is that exposing the parasite to it greatly reduces its DNA, its protein and its energy compounds, and it has been proposed that the fall in cell energy is what halts the building of its large molecules. The fate of the drug in the body is rapid: antimony leaves through the kidneys and most of it appears in the urine of the first hours. But with injections repeated day after day it accumulates slowly in the tissues until it reaches a maximum after some days, and there its toxicity arises.'
  },
  effects: {
    ar: 'الشائع بنصّ النشرة: ضعف شهية وتوعّك وألم عضلات ومفاصل وصداع وخمول. ويشكو قليل من المرضى غثياناً أو قيئاً أو إسهالاً، وأكثر قليلاً منهم ألم بطن. وتُتوقّع تغيّرات في تخطيط القلب، منها نقص سعة موجة تي وانقلابها وطول فترة كيو تي، وأغلبها يزول بإيقاف الدواء. وقد يظهر سعال عابر بعد الحقن مباشرة. والحقن الوريدي قد يُوجع مسار الوريد ثم يجلّطه. وترتفع إنزيمات البنكرياس ارتفاعاً عابراً عادةً، وتنخفض الصفيحات وكريات الدم البيضاء والهيموغلوبين انخفاضاً عابراً.',
    en: 'Common in the words of the label: poor appetite, malaise, muscle and joint pain, headache and lethargy. A small proportion complain of nausea, vomiting or diarrhoea, and slightly more of abdominal pain. ECG changes are to be expected, including reduced T-wave amplitude, T-wave inversion and QT prolongation, most of which resolve when the drug is stopped. A transient cough may follow the injection immediately. Intravenous injection may cause pain along the vein and then clot it. Pancreatic enzymes usually rise transiently, and platelets, white cells and haemoglobin fall transiently.'
  },
  warning: {
    ar: 'أثناء الحقن الوريدي نفسه: إن جاءك سعال أو قيء أو ألم خلف عظمة الصدر فالنشرة تأمر بإيقاف الحقن فوراً. واطلب الطوارئ عند علامات صدمة تحسّسية، وعند خفقان أو إغماء أو نبض غير منتظم لأن طول فترة كيو تي يستدعي إيقاف الدواء إن صار ذا شأن سريري. وراجع في يومك عند ألم شديد أعلى البطن نافذ إلى الظهر مع قيء، أو اصفرار عين، أو نزف من الأنف أو اللثة، أو قلّة بول. وإن كان مرضك في الأنف أو الحلق فقد يشتدّ الالتهاب حول الآفة مع نجاح العلاج نفسه، وضيق النفس هنا حالة طارئة.',
    en: 'During the intravenous injection itself: if coughing, vomiting or pain behind the breastbone occurs, the label orders that administration be stopped immediately. Seek emergency care for signs of anaphylactic shock, and for palpitations, fainting or an irregular pulse, since clinically significant QT prolongation requires the drug be discontinued. Seek review the same day for severe upper abdominal pain boring to the back with vomiting, yellowing of the eyes, bleeding from the nose or gums, or reduced urine. If your disease involves the nose or throat, the inflammation around the lesion may worsen as the treatment succeeds, and breathlessness here is an emergency.'
  },
  interact: {
    ar: 'النشرة تقول إنه لم تُبلَّغ تعارضات دوائية معه، ثم تستثني تحذيراً ثقيلاً: أُبلغ عن اضطراب نظم قلبي وموت مفاجئ حين أُعطي الأمفوتيريسين بي بعده بمدّة قصيرة في إعادة علاج الليشمانيا الحشوية، وتُنصح فترة راحة قدرها أسبوعان بين الاثنين مع تصحيح أملاح الدم أولاً. ويلزم الحذر مع أدوية تطيل فترة كيو تي كالسوتالول والأميودارون. ومن أخذ أنتيمون قريباً يُراقَب مراقبة لصيقة بحثاً عن علامات التسمّم بالأنتيمون كبطء النبض واضطراب النظم.',
    en: 'The label states that no interactions have been reported with it, then makes one heavy exception: cardiac arrhythmias and sudden death have been reported when amphotericin B deoxycholate was given soon after it in the retreatment of visceral leishmaniasis, and a rest period of two weeks between the two is advised with the blood salts corrected first. Caution is required with medicines that prolong the QT interval such as sotalol and amiodarone. Anyone who has recently received antimony is monitored closely for signs of antimony intoxication such as a slow pulse and arrhythmia.'
  },
  avoid: {
    ar: 'ممنوع على من عنده قصور كلوي ذو شأن، وعلى من سبق أن أصابه تفاعل ضارّ خطير من جرعة سابقة. ويُتحرّى الحذر عند مرضى القلب والأوعية، وعند من له تاريخ اضطراب نظم بطيني، وعند من عنده طول خلقي في فترة كيو تي أو يأخذ أدوية تطيلها. وعند مرض الكبد يلزم الحذر لأن الأنتيمون يتراكم في الكبد، مع ملاحظة أن الليشمانيا الحشوية نفسها تُخلّ بوظائف الكبد. ويُحجب في الحمل إلا إذا رجح النفع على الخطر، ولا تُرضع الأم أثناءه. وعند كبار السن يُفضَّل الحقن الموضعي في الآفة الجلدية.',
    en: 'It is forbidden in anyone with significantly impaired kidney function, and in anyone who has had a serious adverse reaction to a previous dose. Caution is required in cardiovascular disease, in a history of ventricular arrhythmia, and in congenital QT prolongation or concurrent QT-prolonging medicines. In liver disease caution is required because antimony accumulates in the liver, noting that visceral leishmaniasis itself disturbs liver function. It is withheld in pregnancy unless the benefit outweighs the risk, and a mother receiving it should not breastfeed. In the elderly, local infiltration of the skin lesion is preferred.'
  },
  updated: '2026-09-10',
  src: [
    'https://www.huidziekten.nl/formularium/SPC-teksten/SPC-tekst-pentostam.pdf',
    'https://www.ncbi.nlm.nih.gov/books/NBK544251/',
    'https://www.who.int/publications/i/item/9789240123298'
  ]
};

RX_BODY['artemether'] = {
  what: {
    ar: 'الأرتيميثر مشتقّ من الأرتيميسينين، وأصل هذا الأخير نبات الشيح الحولي الذي استُخرج منه في الصين. يتحوّل في الجسم إلى مادة فعّالة اسمها ثنائي هيدرو أرتيميسينين وهي التي تحمل أغلب الأثر. يوجد محلولاً زيتياً يُحقن في العضل، ويوجد في الحبوب لكن لا يُعطى فيها وحده أبداً بل مقروناً بشريك طويل البقاء. وميزته سرعة نادرة في تنظيف الدم من الطفيل، وعيبه أن هذه السرعة تقابلها مدّة بقاء قصيرة جداً في الجسم.',
    en: 'Artemether is a derivative of artemisinin, which itself comes from the sweet wormwood plant from which it was extracted in China. In the body it converts into an active substance called dihydroartemisinin, which carries most of the effect. It exists as an oily solution injected into muscle, and in tablets, but in tablets it is never given alone, always paired with a long-lasting partner. Its virtue is a rare speed in clearing the parasite from the blood; its flaw is that this speed is matched by a very short stay in the body.'
  },
  why: {
    ar: 'نشرة الحقنة تعتمدها لعلاج الملاريا بالمنجلية، وتُذكر بوصفها إسعافاً في الملاريا الحرجة وحين يُشتبه في مقاومة أدوية أخرى، وتقصر استعمالها في الملاريا الشديدة على المواضع التي تراجعت فيها فعالية الكينين. ولها موضع عمليّ في المناطق التي لا يتوفّر فيها الأرتيسونات الوريدي. أمّا في الملاريا غير المعقّدة فلا يُستعمل الأرتيميثر منفرداً في الحبوب: منظمة الصحة العالمية تطالب بسحب علاجات الأرتيميسينين المفردة من الأسواق لأنها تعجّل مقاومة الطفيل وتترك انتكاسات.',
    en: 'The injection label approves it for the treatment of falciparum malaria, mentions it as first aid in critical malaria and where resistance to other antimalarials is suspected, and restricts its use in severe malaria to settings where the efficacy of quinine has declined. It has a practical place where intravenous artesunate is unavailable. In uncomplicated malaria, artemether is not used alone as tablets: the World Health Organization calls for single-drug artemisinin treatments to be withdrawn from markets because they hasten parasite resistance and leave recurrences behind.'
  },
  how: {
    ar: 'يعمل الأرتيميثر على أطوار الطفيل داخل كريات الدم الحمراء، فيوقف بناء الحمض النووي والبروتين عنده. وتذكر النشرة أن الآلية غير محسومة، ومن المقترح أنه يفرض على الطفيل إجهاداً تأكسدياً وأيضياً بتعطيل إنزيماته المضادة للأكسدة، ومن المقترح أيضاً أنه يعطّل مضخّة كالسيوم في الطفيل فيتراكم الكالسيوم داخله فيموت. وهو يُحوَّل بسرعة إلى ثنائي هيدرو أرتيميسينين ثم يُطرح، ولذلك يزول أثره قبل أن يُفنى الطفيل كلّه، ومن هنا وجب الشريك.',
    en: 'Artemether acts on the parasite stages inside the red blood cells, halting its building of nucleic acid and protein. The label notes the mechanism is not settled; it has been proposed that it imposes oxidative and metabolic stress on the parasite by disabling its antioxidant enzymes, and also proposed that it disables a calcium pump in the parasite so that calcium accumulates inside it and it dies. It is rapidly converted to dihydroartemisinin and then cleared, so its effect fades before the parasite is wholly destroyed, and hence the need for a partner drug.'
  },
  effects: {
    ar: 'تصفه النشرة بأنه محتمَل بدرجة لافتة وأقلّ سمّية من الكينين والكلوروكين. والمذكور من آثاره: بطء نبض، وتغيّرات في تخطيط القلب، واضطراب هضمي، ودوخة، وألم في موضع الحقن، وتفاعلات جلدية، وحمّى. ولوحظ عند من حُقن في العضل غثيان وهبوط ضغط ودوخة وطنين. وذُكر أيضاً بول داكن وتعرّق ونعاس واصفرار. وقد ينخفض عدد العدلات والشبكيات انخفاضاً عابراً، وقد ترتفع إنزيمات الكبد ارتفاعاً طفيفاً عند أفراد. وقد وُثّق حصار قلبي من الدرجة الأولى عند ثلاثة مرضى.',
    en: 'The label describes it as remarkably well tolerated and less toxic than quinine or chloroquine. Among the effects listed: slow pulse, ECG changes, digestive upset, dizziness, injection-site pain, skin reactions and fever. In those injected into muscle, nausea, low blood pressure, dizziness and tinnitus were seen. Dark urine, sweating, drowsiness and jaundice are also reported. Neutrophil and reticulocyte counts may fall transiently, and liver enzymes may rise slightly in individual cases. First-degree heart block was documented in three patients.'
  },
  warning: {
    ar: 'اطلب الطوارئ عند علامات حساسية شديدة، وعند خفقان أو إغماء أو نبض بطيء جداً. وفي الملاريا الدماغية انتبه: أشارت تجربة إلى احتمال إطالة الغيبوبة وزيادة التشنّجات مع الأرتيميثر، فأي نوبة تشنّج أو تدهور في الوعي حالة طارئة. وراجع في يومك عند اصفرار العين أو بول داكن. والأخطر من كل ذلك سكوت آخر: الحمّى التي ترجع بعد أيام من انتهاء العلاج ليست زكاماً بل قد تكون الملاريا نفسها عادت، لأن الأرتيميثر وحده لا يقتل الطفيل كلّه. عد إلى الطبيب واطلب فحص دم للملاريا لا مسكّناً للحرارة.',
    en: 'Seek emergency care for signs of severe allergy, and for palpitations, fainting or a very slow pulse. In cerebral malaria be alert: a trial suggested coma may be prolonged and seizures increased with artemether, so any seizure or deterioration in consciousness is an emergency. Seek review the same day for yellowing of the eyes or dark urine. More dangerous than all of this is another silence: a fever that returns days after treatment ends is not a cold but may be the malaria itself returning, because artemether alone does not kill the whole parasite. Go back to the doctor and ask for a malaria blood test, not a fever tablet.'
  },
  interact: {
    ar: 'الخطّ المهم هو إطالة فترة كيو تي: تقول النشرة إن الأرتيميثر يطيلها عند بعض المرضى، وتنصح بتجنّب مشاركته أدوية تفعل الشيء نفسه، وتسمّي منها الإريثروميسين والتيرفينادين والبروكاييناميد والكينيدين والديزوبيراميد والأميودارون والسوتالول ومضادات الاكتئاب ثلاثية الحلقة والفينوثيازينات. ويُستقلب الأرتيميثر في الكبد عبر إنزيم سيتوكروم بي أربعمئة وخمسين من نوع ثلاثة أ، فالأدوية التي تحفّز هذا الإنزيم قد تخفض مستواه فتضعف فعاليته.',
    en: 'The important line is QT prolongation: the label states that artemether prolongs it in some patients and advises avoiding medicines that do the same, naming erythromycin, terfenadine, procainamide, quinidine, disopyramide, amiodarone, sotalol, tricyclic antidepressants and phenothiazines among them. Artemether is metabolised in the liver by the cytochrome P450 3A enzyme, so medicines that induce that enzyme may lower its level and weaken its effectiveness.'
  },
  avoid: {
    ar: 'ممنوع عند الحساسية منه، ويُنبَّه إلى الحساسية من الزيت الحامل للحقنة لأنه يختلف بين المنتجات، وبعضها زيت فول سوداني. ولا يُستعمل في الثلث الأول من الحمل إلا إذا رأى الطبيب ضرورته كما في الملاريا الدماغية، فأذى الجنين ظهر في دراسات الحيوان ولا توجد دراسات بشرية محكمة. وتوصي النشرة بتخطيط قلب قبل بدء العلاج عند مرضى القلب. ولا يصلح علاجاً مفرداً في الحبوب. وعند الأطفال تُستعمل محقنة صغيرة لأن الحجم المطلوب صغير، وهذه دقّة تخصّ الممرّض لا المريض.',
    en: 'It is forbidden in hypersensitivity to it, with attention to allergy to the carrier oil of the injection, which differs between products and is peanut oil in some. It is not used in the first trimester of pregnancy unless the doctor judges it essential, as in cerebral malaria, since fetal harm appeared in animal studies and there are no adequate human studies. The label advises an ECG before starting treatment in cardiac patients. It is not suitable as single-drug oral therapy. In children a small syringe is used because the required volume is small, a precision that concerns the nurse rather than the patient.'
  },
  updated: '2026-09-10',
  src: [
    'https://www.nafdac.gov.ng/wp-content/uploads/Files/SMPC/February_2021/SmPC-Arte-Ject-2.pdf',
    'https://www.who.int/news-room/questions-and-answers/item/artemisinin-resistance',
    'https://www.ncbi.nlm.nih.gov/books/NBK544251/'
  ]
};

RX_BODY['artemether-lumefantrine'] = {
  what: {
    ar: 'قرص واحد يجمع دواءين متكاملين ضد الملاريا. الأرتيميثر مشتقّ سريع من الأرتيميسينين يكنس أغلب الطفيل من الدم في وقت قصير ثم يزول من الجسم بسرعة. واللوميفانترين بطيء طويل البقاء يظلّ في الدم بعد أن ينصرف شريكه فيقتل ما تبقّى من الطفيل ويمنع رجوعه. وهذا الزواج بين سريع وبطيء هو معنى العلاج التوليفي المرتكز على الأرتيميسينين، وهو ما تقوم عليه سياسة علاج الملاريا في العالم اليوم.',
    en: 'A single tablet joining two complementary antimalarial medicines. Artemether is a fast artemisinin derivative that sweeps most of the parasite from the blood in a short time and then leaves the body quickly. Lumefantrine is slow and long-lasting, remaining in the blood after its partner departs to kill what is left of the parasite and prevent its return. This marriage of fast and slow is the meaning of artemisinin-based combination therapy, on which world malaria treatment policy rests today.'
  },
  why: {
    ar: 'تعتمده النشرة الأمريكية لعلاج الملاريا الحادّة غير المعقّدة الناتجة عن الطفيل المنجلي، عند البالغين والأطفال من عمر شهور قليلة ومن وزن معيّن فما فوق. وتضع حدّين صريحين: هو غير معتمد للملاريا الشديدة أو المعقّدة، وغير معتمد للوقاية من الملاريا قبل السفر. والفرق بين الشديدة وغير المعقّدة ليس شدّة الشعور بالمرض بل علامات يعرفها الطبيب كاضطراب الوعي والتشنّج والفشل الكلوي وشدّة فقر الدم، وهذه لا تُعالج بالحبوب أصلاً.',
    en: 'The United States label approves it for acute uncomplicated malaria caused by the falciparum parasite, in adults and in children from a few months of age and above a set weight. It sets two explicit limits: it is not approved for severe or complicated malaria, and not approved for malaria prevention before travel. The difference between severe and uncomplicated is not how ill one feels but signs the doctor knows, such as disturbed consciousness, seizures, kidney failure and severe anaemia, and these are not treated with tablets at all.'
  },
  how: {
    ar: 'كلا الشريكين يعمل على الطفيل في طوره داخل كريات الدم الحمراء، لكن بإيقاعين مختلفين. الأرتيميثر يبدأ فوراً ويهبط بعدد الطفيليات هبوطاً حادّاً فتنكسر الحمّى بسرعة، ثم يُطرح خلال ساعات. واللوميفانترين يبقى أياماً ينظّف البقيّة الباقية. وثمّ شرط عملي لا يجوز التهاون فيه: امتصاص اللوميفانترين ضعيف على معدة فارغة ويتحسّن كثيراً مع الطعام، وخاصةً ما فيه دهن ولو قليلاً كاللبن. فالحبّة بلا أكل قد تكون كأنها لم تُؤخذ.',
    en: 'Both partners act on the parasite in its stage inside the red blood cells, but at different tempos. Artemether begins immediately and drops the parasite count sharply so the fever breaks quickly, then is cleared within hours. Lumefantrine remains for days cleaning up what is left. And there is a practical condition that must not be treated lightly: lumefantrine is poorly absorbed on an empty stomach and much better absorbed with food, especially food containing some fat, even milk. A tablet without food may amount to a tablet not taken.'
  },
  effects: {
    ar: 'عند البالغين تذكر النشرة صداعاً وضعف شهية ودوخة ووهناً وألم مفاصل وعضلات. وعند الأطفال يغلب أن يكون المذكور حمّى وسعالاً وقيئاً وضعف شهية وصداعاً. والصعوبة هنا أن كثيراً من هذه الشكاوى هي نفسها أعراض الملاريا، فيصعب فصل الدواء عن المرض. وتقول النشرة إن أغلب الآثار خفيفة وتزول من تلقاء نفسها. وتذكر المصادر أن الدواء قد يبطئ النبض، وأن فترة كيو تي قد تطول، ولهذا كان القلب موضع الاحتياط الأول في هذه البطاقة.',
    en: 'In adults the label lists headache, poor appetite, dizziness, weakness and joint and muscle pain. In children what is listed is mostly fever, cough, vomiting, poor appetite and headache. The difficulty is that many of these complaints are themselves symptoms of malaria, so separating drug from disease is hard. The label states that most effects are mild and resolve on their own. Sources note that the medicine may slow the pulse and that the QT interval may lengthen, which is why the heart is the first point of caution on this card.'
  },
  warning: {
    ar: 'اطلب الطوارئ عند إغماء أو خفقان أو شعور بضربات غير منتظمة، وعند طفح مع ضيق نفس أو تورّم الحلق. وإن تقيّأت الحبّة بعد بلعها بوقت قصير فاتصل بالطبيب لأن الجرعة تحتاج إعادة، وإن عجزت عن الأكل فأخبره لأن الدواء بلا طعام لا يُمتصّ. وأهمّ ما في هذه البطاقة: عودة الحمّى أو القشعريرة بعد أن تحسّنت ليست شفاءً متعثّراً، بل قد تكون الملاريا رجعت أو أُصبت بها من جديد، فالمطلوب فحص دم عاجل لا انتظار. والأخطر: نعاس أو تخليط أو تشنّج أو قلّة بول تعني ملاريا شديدة لا تُعالَج بالحبوب.',
    en: 'Seek emergency care for fainting, palpitations or a feeling of irregular beats, and for a rash with breathlessness or throat swelling. If you vomit the tablet shortly after swallowing it, call your doctor because the dose needs repeating, and if you cannot eat, tell them, because the medicine is not absorbed without food. The most important line on this card: a fever or chills that return after you had improved is not a stalled recovery but may be malaria returning or a new infection, and what is needed is an urgent blood test, not waiting. Most dangerous of all: drowsiness, confusion, seizure or reduced urine mean severe malaria, which tablets do not treat.'
  },
  interact: {
    ar: 'تمنع النشرة مشاركته للمحفّزات القوية لإنزيم سيتوكروم ثلاثة أ أربعة، إذ تهدم الدواء فتُفشل العلاج، ومنها الريفامبين والكاربامازيبين والفينيتوين وعشبة سانت جون. وتنصّ على ألا يُعطى الهالوفانترين وهذا الدواء أحدهما خلال شهر من الآخر. ويلزم الحذر مع كل ما يطيل فترة كيو تي من مضادات اضطراب النظم ومضادات الذهان وبعض المضادات الحيوية. وعصير الجريب فروت يرفع مستوى الدواء فيُتجنّب. وقد تضعف حبوب منع الحمل الهرمونية فتُستعمل وسيلة إضافية.',
    en: 'The label forbids combining it with strong inducers of the cytochrome 3A4 enzyme, which break the medicine down and cause treatment to fail, among them rifampin, carbamazepine, phenytoin and St John wort. It states that halofantrine and this medicine should not be given within a month of each other. Caution is required with everything that prolongs the QT interval, from antiarrhythmics to antipsychotics to certain antibiotics. Grapefruit juice raises the drug level and is avoided. Hormonal contraceptive pills may lose effectiveness, so an additional method is used.'
  },
  avoid: {
    ar: 'ممنوع عند الحساسية من الأرتيميثر أو اللوميفانترين، وممنوع مع المحفّزات القوية لإنزيم سيتوكروم ثلاثة أ أربعة. ويُتجنّب عند من عُرف عنده طول في فترة كيو تي، أو نقص بوتاسيوم أو مغنيسيوم، أو من يأخذ أدوية تطيل هذه الفترة. وأخبر طبيبك إن كان عندك مرض قلب أو كلى أو كبد أو اختلال في أملاح الدم. وفي الحمل والرضاعة يُتّخذ القرار مع الطبيب موازنةً، فالملاريا في الحمل خطر بنفسها. ولا يُستعمل للوقاية ولا للملاريا الشديدة، وهذان منعان يخلط بينهما الناس كثيراً.',
    en: 'It is forbidden in hypersensitivity to artemether or lumefantrine, and forbidden with strong inducers of the cytochrome 3A4 enzyme. It is avoided in anyone known to have QT prolongation, low potassium or magnesium, or who takes medicines that prolong that interval. Tell your doctor if you have heart, kidney or liver disease or a disturbance of the blood salts. In pregnancy and breastfeeding the decision is weighed with the doctor, since malaria in pregnancy is itself a danger. It is not used for prevention nor for severe malaria, two prohibitions people often confuse.'
  },
  updated: '2026-09-10',
  src: [
    'https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=7866ec19-dfac-47d4-a53f-511a12643cbf',
    'https://medlineplus.gov/druginfo/meds/a609024.html'
  ]
};

RX_BODY['artesunate'] = {
  what: {
    ar: 'الأرتيسونات مشتقّ نصف صناعي من الأرتيميسينين، يأتي مسحوقاً في قارورة مع محلول مذيب خاص يُخلط به قبل الحقن مباشرة. يُعطى في الوريد دفعةً بطيئة على دقيقة أو دقيقتين، ولا يُعطى تنقيطاً مستمراً. وما إن يدخل الدم حتى تحوّله إنزيماته إلى ثنائي هيدرو أرتيميسينين، وهو الصورة التي تحمل الفعل. وهو اليوم أول ما يُعطى في الملاريا الشديدة، وقد حلّ محلّ الكينين في هذا الموضع.',
    en: 'Artesunate is a semi-synthetic artemisinin derivative supplied as a powder in a vial with a special diluent mixed into it immediately before injection. It is given into a vein as a slow bolus over a minute or two, and is not given by continuous infusion. As soon as it enters the blood, blood esterases convert it into dihydroartemisinin, the form that carries the action. It is today the first thing given in severe malaria, having displaced quinine in that place.'
  },
  why: {
    ar: 'تعتمده النشرة الأمريكية للعلاج الابتدائي للملاريا الشديدة عند البالغين والأطفال، وتشترط أن يُتبَع دائماً بدورة كاملة من علاج فموي مناسب. والسبب في هذا الشرط أن الحقنة تُنقذ الحياة لكنها لا تُنهي المرض. وتضع النشرة حدّاً آخر: هذا الدواء لا يمسّ الأطوار الكامنة في الكبد، فلا يمنع انتكاس الملاريا من النوعين النشيط والبيضوي، وهما يحتاجان دواءً آخر من فصيلة الأمينوكينولين لاستئصال ما في الكبد وإلا رجع المرض بعد شهور.',
    en: 'The United States label approves it for the initial treatment of severe malaria in adults and children, and requires that it always be followed by a complete course of an appropriate oral antimalarial. The reason for that requirement is that the injection saves life but does not end the disease. The label sets another limit: this medicine does not touch the dormant liver stages, so it does not prevent relapse of vivax and ovale malaria, which need a separate 8-aminoquinoline medicine to clear what is in the liver, or the illness returns months later.'
  },
  how: {
    ar: 'الأرتيسونات يتحوّل فور دخوله الدم إلى ثنائي هيدرو أرتيميسينين بفعل إنزيمات الدم نفسها، وهذا التحوّل السريع هو سرّ سرعة أثره. والفصيلة كلها تعمل داخل كرية الدم الحمراء المصابة: ترتبط بالهيم ويتفكّك الجسر البيروكسيدي فيها فتنطلق جذور حرّة سامّة تمزّق الطفيل. ولهذا ينخفض عدد الطفيليات في الدم انخفاضاً حادّاً وسريعاً أكثر مما يفعله الكينين. وتذكر النشرة أن الدواء بالكمية المعتمدة لا يُحدث زيادة كبيرة في فترة كيو تي، وهذه ميزة على غيره.',
    en: 'Artesunate converts to dihydroartemisinin the moment it enters the blood, through the blood enzymes themselves, and that rapid conversion is the secret of its speed. The whole class works inside the infected red cell: it binds to haem, whose peroxide bridge then breaks, releasing toxic free radicals that tear the parasite apart. This is why the parasite count in the blood falls more sharply and faster than with quinine. The label notes that at the approved amount the drug does not cause a large increase in the QT interval, an advantage over others.'
  },
  effects: {
    ar: 'في التجربة الكبرى على الملاريا الشديدة كان الأكثر تسجيلاً فشلاً كلوياً يحتاج غسيلاً، وبولاً محتوياً على الهيموغلوبين، ويرقاناً. وفي دراسة أمريكية سُجّل فقر دم عند ثلثي المرضى تقريباً، وارتفاع إنزيمات الكبد، ونقص صفيحات، وارتفاع بيليروبين. ويصعب هنا فصل الدواء عن المرض لأن الملاريا الشديدة نفسها تُتلف الكلى والكبد والدم. ومن الآثار الأخفّ: دوخة وصداع وطنين وتغيّر حاسّة التذوّق وسعال وطفح وألم بطن وقيء. وأُبلغ نادراً عن التهاب البنكرياس وعن حساسية شديدة.',
    en: 'In the large severe-malaria trial, what was recorded most often was kidney failure requiring dialysis, urine containing haemoglobin, and jaundice. In a United States study, anaemia was recorded in about two-thirds of patients, along with raised liver enzymes, low platelets and raised bilirubin. Separating drug from disease is difficult here, since severe malaria itself damages the kidneys, liver and blood. Among the lighter effects: dizziness, headache, tinnitus, altered taste, cough, rash, abdominal pain and vomiting. Pancreatitis and severe hypersensitivity have been reported rarely.'
  },
  warning: {
    ar: 'أهمّ ما في هذه البطاقة أثر لا يظهر إلا بعد أن تخرج من المستشفى: انحلال الدم المتأخّر بعد الأرتيسونات، ويبدأ بعد أسبوع أو أكثر من بدء العلاج. تُلزم النشرة بمتابعتك أربعة أسابيع بعد العلاج بحثاً عنه. فإن شحب لونك أو زاد تعبك أو ضاق نفسك عند المجهود أو اصفرّت عيناك أو اسودّ بولك بعد أن تحسّنت، فارجع فوراً واطلب تحليل دم؛ بعض الحالات احتاجت نقل دم. واطلب الطوارئ إن هبط ضغطك أو ضاق نفسك أو ظهر شرى أو طفح واسع أثناء الحقن نفسه.',
    en: 'The most important thing on this card is an effect that appears only after you leave hospital: post-artesunate delayed haemolysis, beginning a week or more after treatment starts. The label requires that you be monitored for four weeks after treatment looking for it. So if you turn pale, tire more, become breathless on exertion, your eyes yellow or your urine darkens after you had improved, go back at once and ask for a blood test; some cases have needed transfusion. Seek emergency care if your blood pressure drops, you become breathless, or hives or a widespread rash appear during the injection itself.'
  },
  interact: {
    ar: 'تذكر النشرة خطّين. الأول أدوية تُنقص المادة الفعّالة فتضعف العلاج: الريتونافير والنيفيرابين ومحفّزات إنزيم الجلوكورونيل ترانسفيراز القوية كالريفامبين والكاربامازيبين والفينيتوين، وعند استعمالها معاً تُراقب فعالية العلاج. والثاني مثبّطات هذا الإنزيم القوية كالأكسيتينيب والفانديتانيب والإيماتينيب والديكلوفيناك، فقد ترفع المادة الفعّالة فتزيد آثارها، وتُراقب الآثار الجانبية. وهذه مسائل يديرها فريق المستشفى، لكن ذكر قائمة أدويتك عند الدخول هو ما يجعلها ممكنة.',
    en: 'The label notes two lines. The first is medicines that lower the active metabolite and so weaken the treatment: ritonavir, nevirapine, and strong inducers of the glucuronyl transferase enzyme such as rifampin, carbamazepine and phenytoin; when used together, antimalarial efficacy is monitored. The second is strong inhibitors of that enzyme such as axitinib, vandetanib, imatinib and diclofenac, which may raise the active metabolite and increase its effects, so adverse reactions are monitored. These are matters the hospital team manages, but naming your medicine list on admission is what makes that possible.'
  },
  avoid: {
    ar: 'المانع الوحيد في النشرة هو حساسية شديدة سابقة من الأرتيسونات كالتأق. وأمّا الحمل فالنشرة صريحة: تأخير علاج الملاريا الشديدة في الحمل قد يقتل الأم والجنين معاً، فلا يُؤجَّل العلاج بسبب الحمل، وإن ظهر في الحيوان أثر على الأجنّة فإن الخبرة الطويلة بأدوية هذه الفصيلة عند الحوامل لم تكشف زيادة في التشوّهات. وتوجد المادة الفعّالة في حليب الأم فيوازَن الأمر. ولا تُعدَّل الكمية لأجل قصور الكلى أو الكبد، لأن أغلب مرضى الملاريا الشديدة عندهم شيء من ذلك أصلاً.',
    en: 'The only bar in the label is a previous serious hypersensitivity to artesunate such as anaphylaxis. As for pregnancy, the label is explicit: delaying treatment of severe malaria in pregnancy may kill both mother and fetus, so treatment is not postponed because of pregnancy, and although an effect on embryos appeared in animals, long experience with this class in pregnant women has not revealed an increase in malformations. The active metabolite is present in breast milk, so the matter is weighed. No adjustment is made for kidney or liver impairment, since most patients with severe malaria have some degree of both already.'
  },
  updated: '2026-09-10',
  src: [
    'https://www.accessdata.fda.gov/drugsatfda_docs/label/2023/213036s004lbl.pdf',
    'https://www.ncbi.nlm.nih.gov/books/NBK544251/'
  ]
};

RX_BODY['artesunate-amodiaquine'] = {
  what: {
    ar: 'قرص يجمع الأرتيسونات مع الأمودياكين. الأرتيسونات مشتقّ الأرتيميسينين السريع الذي يكنس الطفيل من الدم، والأمودياكين من فصيلة الأمينوكينولين الرباعي، قريب الكلوروكين، بطيء الزوال فيبقى ليقتل ما تبقّى. وهذه التركيبة من أكثر ما يُستعمل في غرب أفريقيا، وتُصنَّف من العلاجات التوليفية المرتكزة على الأرتيميسينين. وتُبلع بالماء ولا تُؤخذ مع وجبة عالية الدهن، خلافاً لتركيبة الأرتيميثر مع اللوميفانترين.',
    en: 'A tablet joining artesunate with amodiaquine. Artesunate is the fast artemisinin derivative that sweeps the parasite from the blood; amodiaquine is a 4-aminoquinoline, a relative of chloroquine, slow to clear so that it remains to kill what is left. This combination is among the most used in West Africa and is classed as an artemisinin-based combination therapy. It is swallowed with water and is not taken with a high-fat meal, unlike the artemether and lumefantrine combination.'
  },
  why: {
    ar: 'تعتمده النشرة لعلاج الملاريا غير المعقّدة الناتجة عن الطفيل المنجلي حين تكون سلالاته حسّاسة للأمودياكين وللأرتيسونات. وتشدّد على قيود ثلاثة: لا يُستعمل في مناطق تنتشر فيها مقاومة الأمودياكين لأنه يصير عملياً كعلاج بالأرتيسونات وحده فتزيد مقاومته زيادة كبيرة؛ ولم يُقيَّم في الملاريا المعقّدة فلا يُنصح بها؛ ولم يُقيَّم في الأنواع الأخرى من الطفيل فلا يُنصح بها. وهذا الدواء ممنوع للوقاية من الملاريا منعاً مطلقاً، وسيأتي بيان السبب.',
    en: 'The label approves it for uncomplicated malaria caused by falciparum strains susceptible to amodiaquine and to artesunate. It stresses three limits: it is not used in regions where amodiaquine resistance is widespread, since it then amounts in practice to artesunate alone and resistance to artesunate rises significantly; it has not been evaluated in complicated malaria, so it is not recommended there; and it has not been evaluated in the other parasite species, so it is not recommended for them. This medicine is absolutely forbidden for malaria prevention, and the reason follows.'
  },
  how: {
    ar: 'الأرتيسونات يعمل بالطريقة المعروفة عن فصيلته: يتحوّل إلى ثنائي هيدرو أرتيميسينين ويطلق داخل الكرية المصابة جذوراً حرّة تفتك بالطفيل بسرعة. والأمودياكين من أقارب الكلوروكين، يعمل داخل فجوة الطفيل الهاضمة فيعرقل تخلّصه من فضلات الهيم السامّة عليه. وتذكر النشرة أن الأمودياكين يفعل في بعض السلالات المقاومة للكلوروكين وإن كان بينهما مقاومة متقاطعة. وتنبّه إلى أن اجتماع الاثنين يخفض تركيز المادة الفعّالة للأرتيسونات بعض الشيء وهذا معروف ومحسوب.',
    en: 'Artesunate works in the way known for its class: it converts to dihydroartemisinin and releases free radicals inside the infected red cell that destroy the parasite quickly. Amodiaquine is a relative of chloroquine, acting inside the parasite digestive vacuole to obstruct its disposal of haem waste that is toxic to it. The label notes that amodiaquine is effective against some chloroquine-resistant strains, though cross-resistance exists between them. It also notes that combining the two lowers the concentration of the artesunate active metabolite somewhat, which is known and accounted for.'
  },
  effects: {
    ar: 'أغلب ما لوحظ في الدراسات يشبه أعراض نوبة الملاريا نفسها. والأكثر تواتراً: ضعف شهية، وألم بطن، وغثيان، ووهن، ونعاس، وأرق، وسعال. والأشدّ فيما رُصد: وهن شديد، وفقر دم، ودوار. ومن الشائع طول فترة كيو تي في تخطيط القلب. ومن غير الشائع: فقر دم، ونقص سكر، وتنميل، وبطء نبض، واضطراب نظم، وحكّة وطفح وتورّم الوجه، وهلوسة. وقد تظهر اضطرابات حركية خارج هرمية مثل تصلّب أو حركات لا إرادية أو خروج اللسان، حتى بعد أول قرص، وتزول بإيقاف الدواء.',
    en: 'Most of what was observed in the studies resembles the symptoms of a malaria attack itself. The most frequent: poor appetite, abdominal pain, nausea, weakness, drowsiness, insomnia and cough. The most serious observed: severe weakness, anaemia and vertigo. QT prolongation on the ECG is common. Uncommonly: anaemia, low blood sugar, tingling, slow pulse, arrhythmia, itching, rash, facial swelling and hallucination. Extrapyramidal movement disorders such as stiffness, involuntary movements or tongue protrusion may appear, even after a single dose, and resolve when the medicine is stopped.'
  },
  warning: {
    ar: 'هذه أهم فقرة في البطاقة، وتنصّ النشرة على أن الاستمرار في الدواء بعدها يزيد خطر الموت. أوقفه واذهب في يومك إن جاءتك حمّى مع التهاب حلق أو لوزتين أو تقرّحات في الفم، فهذه صورة انهيار كريات الدم البيضاء. وأوقفه واذهب إن اصفرّت عيناك أو اسودّ بولك أو غثيت مع ألم بطن، فهذه صورة التهاب كبد قد يكون قاتلاً. واطلب الطوارئ عند تصلّب أو التواء في الرقبة أو حركات لا إرادية أو خروج اللسان، وعند إغماء أو خفقان. وأي حمّى ترجع بعد التحسّن تستدعي فحص دم لا انتظاراً.',
    en: 'This is the most important paragraph on the card, and the label states that continuing the medicine after these signs increases the risk of death. Stop it and go the same day if you develop fever with a sore throat or tonsillitis or mouth ulcers, which is the picture of a collapse in the white cells. Stop it and go if your eyes yellow, your urine darkens, or you feel sick with abdominal pain, which is the picture of a hepatitis that can be fatal. Seek emergency care for stiffness, a twisted neck, involuntary movements or tongue protrusion, and for fainting or palpitations. And any fever returning after improvement calls for a blood test, not waiting.'
  },
  interact: {
    ar: 'يُتجنّب إعطاؤه مع الإيفافيرينز لأن هذا الاجتماع قد يُحدث سمّية كبدية شديدة. ولا يُنصح بمشاركته مثبّطات إنزيمَي سيتوكروم اثنين أ ستة واثنين ج ثمانية، ومنها التريميثوبريم والكيتوكونازول والريتونافير والساكوينافير واللوبينافير والجيمفيبروزيل والمونتيلوكاست. ويلزم الانتباه مع أدوية الإيدز والسلّ عموماً بحثاً عن سمّية كبدية أو نقص عدلات. وهو نفسه يثبّط إنزيم سيتوكروم اثنين د ستة فيؤثّر في بعض حاصرات بيتا ومضادات الاكتئاب ومضادات الذهان. ويُتجنّب مع كل ما يطيل فترة كيو تي أو يؤذي الكبد أو الدم.',
    en: 'Giving it with efavirenz is avoided, because that combination can cause marked liver toxicity. Combining it with inhibitors of the cytochrome 2A6 and 2C8 enzymes is not recommended, among them trimethoprim, ketoconazole, ritonavir, saquinavir, lopinavir, gemfibrozil and montelukast. Vigilance is needed with HIV and tuberculosis medicines generally, watching for liver toxicity or a fall in neutrophils. Amodiaquine itself inhibits the cytochrome 2D6 enzyme and so affects some beta blockers, antidepressants and antipsychotics. It is avoided with everything that prolongs the QT interval or harms the liver or blood.'
  },
  avoid: {
    ar: 'ممنوع عند الحساسية من أي من مكوّنيه، وممنوع على من سبق أن أصابه أذى كبدي أثناء علاج بالأمودياكين، وعلى من سبقت له مشكلة في الدم أثناء علاج به، وعلى من عنده اعتلال في شبكية العين إذا تكرّر العلاج. وممنوع منعاً باتاً للوقاية من الملاريا، لأن استعمال الأمودياكين وقايةً يورث خطراً غير مقبول من انهيار كريات الدم البيضاء ومن سمّية الكبد. ويلزم الحذر في قصور الكلى أو الكبد. ولا يُستعمل في الثلث الأول من الحمل إلا إذا كان منقذاً للحياة ولم يصلح غيره، والإرضاع مسموح لأن ما ينتقل إلى الحليب قليل.',
    en: 'It is forbidden in hypersensitivity to either component, forbidden to anyone who suffered liver injury during amodiaquine treatment, to anyone who had a blood disorder during such treatment, and to anyone with retinopathy where treatment is repeated. It is absolutely forbidden for malaria prevention, because using amodiaquine for prophylaxis carries an unacceptable risk of a collapse in the white cells and of liver toxicity. Caution is needed in kidney or liver impairment. It is not used in the first trimester of pregnancy unless it is life-saving and nothing else is suitable, and breastfeeding is permitted because the amounts passing into milk are small.'
  },
  updated: '2026-09-10',
  src: [
    'https://extranet.who.int/prequal/sites/default/files/whopar_files/MA058part4v3.pdf',
    'https://www.who.int/news-room/questions-and-answers/item/artemisinin-resistance'
  ]
};

RX_BODY['artesunate-mefloquine'] = {
  what: {
    ar: 'قرص يجمع الأرتيسونات مع الميفلوكين. الأرتيسونات هو السريع الذي ينظّف الدم من الطفيل، والميفلوكين قريب الكينين، طويل البقاء في الجسم، يظلّ أسابيع ليمنع رجوع المرض. وهذا البقاء الطويل هو مصدر قوّته ومصدر مشكلته معاً: أثره العصبي والنفسي قد يمتدّ بعد انتهاء العلاج بأسابيع. ولذلك يُمنع إعطاؤه لمن أخذ الميفلوكين في الشهرين الماضيين، ويُصنّف من العلاجات التوليفية المرتكزة على الأرتيميسينين.',
    en: 'A tablet joining artesunate with mefloquine. Artesunate is the fast agent that clears the parasite from the blood; mefloquine is a relative of quinine, long-lasting in the body, staying for weeks to prevent the illness returning. That long stay is the source of both its strength and its problem: its effects on the nerves and the mind may extend for weeks after treatment ends. For that reason it must not be given to anyone who took mefloquine in the past two months, and it is classed as an artemisinin-based combination therapy.'
  },
  why: {
    ar: 'يعتمده تقييم منظمة الصحة العالمية لعلاج الملاريا الحادّة غير المعقّدة بالطفيل المنجلي، سواء كانت العدوى به وحده أو مختلطة، عند البالغين والمراهقين والأطفال من نحو سنّ السابعة. ويضع حدوداً: لم يُقيَّم في الملاريا المعقّدة فلا يُنصح به فيها؛ والأدلّة غير كافية لاستعماله في الأنواع الأخرى من الطفيل؛ والأدلّة غير كافية لاستعماله وقايةً من الملاريا. وإن لم يتحسّن المريض خلال يومين أو ثلاثة من إتمام العلاج وجب أن يُعاد تقييمه.',
    en: 'The World Health Organization assessment approves it for acute uncomplicated falciparum malaria, whether as a single infection or a mixed one, in adults, adolescents and children from about the age of seven. It sets limits: it has not been evaluated in complicated malaria and is not recommended there; the evidence is insufficient for the other parasite species; and the evidence is insufficient for using it as malaria prevention. If the patient has not improved within two or three days of completing treatment, they must be reassessed.'
  },
  how: {
    ar: 'الأرتيسونات ومادّته الفعّالة ثنائي هيدرو أرتيميسينين سامّان للطفيل بتراكيز ضئيلة جداً، وتزيد كرية الدم المصابة من التقاطهما، فيقع الفعل حيث الطفيل بالضبط. والميفلوكين شبيه بالكينين في طريقة عمله على الطفيل داخل الكرية، لكنه يمكث في الجسم مدّة أطول بكثير من شريكه فيغطّي ما بعد انتهاء أثر الأرتيسونات. وتُبلع الأقراص كاملة مع الطعام أو بدونه، ومن عجز عن بلعها فتُفتّت في ماء نظيف على ملعقة ثم يُشرب بعدها ماء.',
    en: 'Artesunate and its active metabolite dihydroartemisinin are toxic to the parasite at very small concentrations, and the infected red cell takes them up preferentially, so the action falls exactly where the parasite is. Mefloquine resembles quinine in the way it acts on the parasite inside the cell, but it stays in the body far longer than its partner and so covers the period after the artesunate effect has ended. The tablets are swallowed whole with or without food, and anyone unable to swallow them lets them disintegrate in clean water on a spoon, then drinks water after.'
  },
  effects: {
    ar: 'الأكثر تسجيلاً في التجربة المحورية: صداع ودوار وقيء وغثيان وإرهاق وحمّى وألم مفاصل وعضلات وضعف شهية واضطراب نوم وخفقان. والدوار واضطراب النوم شائعان جداً بنصّ التقييم، والصداع شائع. وذُكرت هلوسة بصرية بتواتر غير شائع. وفي الأدبيات الطبية ذُكر قلق وأحلام غريبة وشرى وتفاعلات تحسّسية وطفح قد يبلغ صوراً شديدة، ورعشة وتخليط وتنميل. ونادراً ذُكرت أحداث نفسية خطيرة كنوبة تشنّج ومتلازمة اكتئابية وذهان حادّ، وانحلال دم حادّ داخل الأوعية.',
    en: 'Most recorded in the pivotal trial: headache, dizziness, vomiting, nausea, fatigue, fever, joint and muscle pain, poor appetite, sleep disturbance and palpitations. Dizziness and sleep disturbance are very common in the words of the assessment, and headache is common. Visual hallucination was reported at an uncommon frequency. In the medical literature, anxiety, abnormal dreams, hives, allergic reactions and rashes that may reach severe forms, along with tremor, confusion and numbness, are reported. Rarely, serious psychiatric events such as seizure, a depressive syndrome and acute psychosis have been reported, as has acute intravascular haemolysis.'
  },
  warning: {
    ar: 'أوقف الدواء واطلب المساعدة الطبية فوراً إن ظهر قلق شديد أو تخليط أو اكتئاب أو هلوسة أو أفكار بإيذاء النفس أو نوبة تشنّج، فهذه أحداث نفسية وعصبية معروفة عن الميفلوكين وقد تسبق أذى أكبر. واذهب للطوارئ عند اسوداد البول مع شحوب وإرهاق، فهذه صورة انحلال دم حادّ، وعند طفح يتقشّر أو يصنع فقاعات، وعند إغماء أو خفقان. ولا تقد سيارة ولا تشغّل آلة إن أصابك دوار أو دوخة، فالتقييم يوصي بالامتناع عن ذلك ثلاثة أسابيع بعد العلاج لأن الدواء يبقى طويلاً.',
    en: 'Stop the medicine and seek medical help at once if severe anxiety, confusion, depression, hallucinations, thoughts of self-harm or a seizure appear, as these are neuropsychiatric events known with mefloquine and may precede worse harm. Go to emergency for dark urine with pallor and exhaustion, which is the picture of acute haemolysis, for a rash that peels or blisters, and for fainting or palpitations. Do not drive or operate machinery if dizziness or vertigo affects you; the assessment advises abstaining for three weeks after treatment, because the medicine lingers.'
  },
  interact: {
    ar: 'ممنوع مع الهالوفانترين معاً أو خلال ثلاثة أسابيع بعده لأن اجتماعهما قد يطيل فترة كيو تي إطالة قاتلة، وممنوع مع الكيتوكونازول للسبب نفسه. ويزيد اجتماعه مع الكلوروكين أو الكينين خطر التشنّج. ويخفض الميفلوكين مستويات أدوية الصرع كالكاربامازيبين والفينوباربيتال والفينيتوين وحمض الفالبرويك. وأُبلغ عن نزف خطير مع الوارفارين فتُراقب سيولة الدم. وتُرفع مستوياته بالأمبيسيلين والتتراسيكلين والميتوكلوبراميد، وتُخفض بالريفامبيسين. ويلزم الحذر مع ما يبطئ النبض كالديجوكسين وحاصرات بيتا والفيراباميل والديلتيازيم.',
    en: 'It is forbidden together with halofantrine or within three weeks after it, because the combination may prolong the QT interval fatally, and forbidden with ketoconazole for the same reason. Combining it with chloroquine or quinine increases the risk of seizures. Mefloquine lowers the levels of epilepsy medicines such as carbamazepine, phenobarbital, phenytoin and valproic acid. Serious bleeding has been reported with warfarin, so clotting is monitored. Its levels are raised by ampicillin, tetracycline and metoclopramide, and lowered by rifampicin. Caution is needed with things that slow the pulse, such as digoxin, beta blockers, verapamil and diltiazem.'
  },
  avoid: {
    ar: 'ممنوع عند الحساسية من مكوّناته، وعند الحساسية المعروفة من الكينين أو الكينيدين أو أي من الأرتيميسينينات. وممنوع في فترة النقاهة من الملاريا الشديدة لأن الميفلوكين يزيد خطر التشنّج فيها. وممنوع مع الهالوفانترين أو الكيتوكونازول أو قريباً منهما. ولا يُعطى خلال شهرين من علاج سابق بالميفلوكين. ويلزم الحذر عند من عنده خلل في توصيل القلب أو اضطراب نظم، وعند من له تاريخ نوبات تشنّج، وعند قصور الكبد الشديد. ويُقصر في الثلث الأول من الحمل على الحالات التي لا بديل فيها.',
    en: 'It is forbidden in hypersensitivity to its components, and in known hypersensitivity to quinine, quinidine or any artemisinin. It is forbidden during the recovery period from severe malaria, because mefloquine increases the risk of seizures then. It is forbidden with halofantrine or ketoconazole or close to either. It is not given within two months of previous mefloquine treatment. Caution is needed in cardiac conduction defects or arrhythmias, in a history of seizures, and in severe liver impairment. In the first trimester of pregnancy it is limited to situations where no alternative exists.'
  },
  updated: '2026-09-10',
  src: [
    'https://extranet.who.int/prequal/sites/default/files/whopar_files/MA079part4v2.pdf',
    'https://www.who.int/news-room/questions-and-answers/item/artemisinin-resistance'
  ]
};

RX_BODY['artesunate-pyronaridine'] = {
  what: {
    ar: 'قرص برتقالي يجمع البيروناريدين مع الأرتيسونات، وله شكل حبيبات للأطفال الصغار. حصل على رأي علمي إيجابي من الوكالة الأوروبية للأدوية بالتعاون مع منظمة الصحة العالمية، وهو مسار مخصّص لأدوية تُستعمل خارج أوروبا. الأرتيسونات هو الطرف السريع، والبيروناريدين هو الشريك البطيء الذي يقتل الطفيل في الدم على مهل. ويحتوي القرص على ملوّنَي التارترازين والأصفر الغروب، وهما قد يثيران تفاعلاً تحسّسياً عند بعض الناس.',
    en: 'An orange tablet joining pyronaridine with artesunate, with a granule form for small children. It received a positive scientific opinion from the European Medicines Agency in cooperation with the World Health Organization, a route intended for medicines used outside Europe. Artesunate is the fast partner, pyronaridine the slow one that kills the blood-stage parasite at its own pace. The tablet contains the colourings tartrazine and sunset yellow, which can provoke an allergic reaction in some people.'
  },
  why: {
    ar: 'يعتمده التقييم لعلاج الملاريا الحادّة غير المعقّدة الناتجة عن الطفيل المنجلي أو عن الطفيل النشيط، عند البالغين والأطفال فوق حدّ معيّن من الوزن. وقدرته على النوعين معاً ميزة قليل من التركيبات يملكها. لكن يُشترط في النوع النشيط أن يُتبَع بدواء يستأصل الطور الكامن في الكبد كالبريماكين، وإلا رجع المرض. ولا يُستعمل وقايةً من الملاريا، ولا يُستعمل في الملاريا الشديدة ولا الدماغية ولا في أي مظهر معقّد، فمريض الملاريا الشديدة ليس مرشّحاً لعلاج بالفم أصلاً.',
    en: 'The assessment approves it for acute uncomplicated malaria caused by the falciparum parasite or by the vivax parasite, in adults and children above a set weight. Its ability against both species is an advantage few combinations have. But in vivax malaria it must be followed by a medicine that clears the dormant liver stage, such as primaquine, or the illness returns. It is not used for malaria prevention, nor in severe or cerebral malaria or any complicated manifestation, since a patient with severe malaria is not a candidate for oral therapy at all.'
  },
  how: {
    ar: 'الأرتيسونات يعمل بطريقة فصيلته: يتحوّل إلى ثنائي هيدرو أرتيميسينين ويقتل الطفيل داخل الكرية الحمراء بسرعة كبيرة ثم يزول. والبيروناريدين قاتل للطفيل في طوره الدموي أيضاً، لكنه يبقى مدّة أطول فيغطّي ما بعد زوال شريكه، وهذا هو منطق التركيبة كلها. ويُبلع القرص مع الطعام أو بدونه. وإن تقيّأه المريض بعد بلعه بوقت قصير أُعيدت الجرعة، وإن تقيّأ الإعادة أيضاً انتُقل إلى دواء آخر. والإسهال الخفيف لا يوجب تغيير العلاج.',
    en: 'Artesunate works in the manner of its class: it converts to dihydroartemisinin and kills the parasite inside the red cell very quickly, then clears. Pyronaridine also kills the blood-stage parasite, but it remains longer and so covers the period after its partner has gone, which is the whole logic of the combination. The tablet is swallowed with or without food. If the patient vomits it shortly after swallowing, the dose is repeated, and if the repeat is vomited too, another medicine is used instead. Mild diarrhoea does not require a change of treatment.'
  },
  effects: {
    ar: 'قُيّمت سلامته في تجارب شملت آلاف المرضى. والشائع بنصّ التقييم: صداع، وارتفاع الحمضات، ونقص العدلات، وفقر دم، وارتفاع الصفيحات، وقيء، وألم بطن، وبطء نبض، وارتفاع إنزيمات الكبد، ونقص سكر الدم. وارتفاع الإنزيمات هو أشهر ما يُذكر عنه: يقع عند نحو واحد من كل عشرين، ويبدأ في الأيام الأولى ثم يعود إلى طبيعته في الغالب خلال أسبوعين، وينسبه التقييم إلى البيروناريدين لا إلى الأرتيسونات. ومن غير الشائع: خفقان، وإمساك أو إسهال، ودوار، ونقص كريات.',
    en: 'Its safety was assessed in trials covering thousands of patients. Common in the words of the assessment: headache, raised eosinophils, low neutrophils, anaemia, raised platelets, vomiting, abdominal pain, slow pulse, raised liver enzymes and low blood sugar. The enzyme rise is what it is best known for: it occurs in about one in twenty, begins in the first days and usually returns to normal within two weeks, and the assessment attributes it to pyronaridine rather than artesunate. Uncommonly: palpitations, constipation or diarrhoea, vertigo and falls in blood cell counts.'
  },
  warning: {
    ar: 'انتبه لكبدك، وخاصةً في الأسبوعين الأولين بعد أخذ الدواء: إن غثيت أو أوجعك بطنك مع اصفرار في العين أو الجلد، أو اسودّ بولك، أو حكّ جسمك بلا طفح، أو أصابك إرهاق غير معتاد، فأوقف الدواء واطلب فحص وظائف الكبد في يومك. واطلب الطوارئ عند علامات حساسية شديدة، فملوّنات القرص قد تسبّب احمراراً وشرى وضيق نفس وإغماءً وهبوط ضغط. وراجع عند شحوب شديد أو ضيق نفس لأن الهيموغلوبين قد ينخفض أثناء العلاج. وإن عادت الملاريا خلال أربعة أسابيع فالعلاج يكون بدواء آخر لا بإعادة هذا.',
    en: 'Watch your liver, especially in the first two weeks after taking the medicine: if you feel sick or your abdomen aches along with yellowing of the eyes or skin, or your urine darkens, or you itch without a rash, or unusual exhaustion sets in, stop the medicine and ask for liver function tests the same day. Seek emergency care for signs of severe allergy, since the tablet colourings can cause flushing, hives, breathlessness, faintness and a drop in blood pressure. Seek review for marked pallor or breathlessness, as haemoglobin may fall during treatment. And if malaria returns within four weeks, treatment is with a different medicine, not a repeat of this one.'
  },
  interact: {
    ar: 'الحذر الأول من الأدوية المؤذية للكبد لأن الأثر قد يتراكم: يذكر التقييم الريفامبين والكاربامازيبين والإيزونيازيد والباراسيتامول. ويلزم حذر خاص مع ما يُعرف بسمّيته على الميتوكوندريا كحمض الفالبرويك وأدوية الإيدز، ومع الأعشاب الطبية. والبيروناريدين يثبّط إنزيم سيتوكروم اثنين د ستة فيرفع مستوى الميتوبرولول والفليكاينيد والبروبافينون. ويثبّط ناقل بي جي بي فقد يلزم مراقبة الديجوكسين والدابيجاتران. وقد يقلّ نشاط إنزيم واحد أ اثنين فيُحذر مع الثيوفيلّين. ومحفّزات الإنزيمات كالريفامبيسين وعشبة سانت جون تخفض المادة الفعّالة.',
    en: 'The first caution concerns medicines that harm the liver, since the effect may be cumulative: the assessment names rifampin, carbamazepine, isoniazid and paracetamol. Particular caution is needed with agents known for mitochondrial toxicity such as valproic acid and HIV medicines, and with herbal remedies. Pyronaridine inhibits the cytochrome 2D6 enzyme and so raises the levels of metoprolol, flecainide and propafenone. It inhibits the P-gp transporter, so digoxin and dabigatran may need monitoring. Activity of the 1A2 enzyme may fall, so caution is advised with theophylline. Enzyme inducers such as rifampicin and St John wort lower the active metabolite.'
  },
  avoid: {
    ar: 'ممنوع عند الحساسية من البيروناريدين أو الأرتيسونات أو أي مكوّن. وممنوع على من عنده علامات أو أعراض أذى كبدي كغثيان أو ألم بطن مع يرقان، وعلى من عنده مرض كبد شديد معروف كتشمّع غير معاوَض من درجة تشايلد بو ب أو ج. وممنوع في القصور الكلوي الشديد. ولا يُنصح به في الثلث الأول من الحمل ما دام غيره متاحاً وفعّالاً، ولا يُمنع في حالة مهدِّدة للحياة. ويلزم الحذر عند كبار السن، وعند من هيموغلوبينه منخفض، وعند حاملي التهاب الكبد أو فيروس الإيدز، وعند الأطفال الصغار سيّئي التغذية.',
    en: 'It is forbidden in hypersensitivity to pyronaridine, artesunate or any component. It is forbidden to anyone with signs or symptoms of liver injury, such as nausea or abdominal pain with jaundice, and to anyone with known severe liver disease such as decompensated cirrhosis of Child-Pugh stage B or C. It is forbidden in severe kidney impairment. It is not recommended in the first trimester of pregnancy while other suitable and effective medicines are available, and it is not withheld in a life-threatening situation. Caution is needed in the elderly, in those with low haemoglobin, in carriers of hepatitis or HIV, and in malnourished young children.'
  },
  updated: '2026-09-10',
  src: [
    'https://www.ema.europa.eu/en/documents/outside-eu-product-information/pyramax-product-information_en.pdf',
    'https://www.ema.europa.eu/en/documents/outside-eu-rmp-summary/pyramax-risk-management-plan_en.pdf'
  ]
};
